@Test
public void testReplaceMethods() throws Exception {
    assertEquals("methods=aaa,bbb", ParseUtils.replaceParameter(null, "methods", "aaa,bbb"));
    assertEquals("methods=aaa,bbb", ParseUtils.replaceParameter("", "methods", "aaa,bbb"));
    assertEquals("version=1.0.0&application=morgan&weight=10&methods=aaa,bbb", ParseUtils.replaceParameter("version=1.0.0&application=morgan&weight=10", "methods", "aaa,bbb"));
    assertEquals("version=1.0.0&methods=ccc,ddd&application=morgan&weight=10", ParseUtils.replaceParameter("version=1.0.0&methods=aaa,bbb&application=morgan&weight=10", "methods", "ccc,ddd"));
    assertEquals("dubbo://172.22.3.91:20880/memberService?version=1.0.0&application=morgan&weight=10&methods=aaa,bbb", ParseUtils.replaceParameter("dubbo://172.22.3.91:20880/memberService?version=1.0.0&application=morgan&weight=10", "methods", "aaa,bbb"));
    assertEquals("dubbo://172.22.3.91:20880/memberService?version=1.0.0&methods=ccc,ddd&application=morgan&weight=10", ParseUtils.replaceParameter("dubbo://172.22.3.91:20880/memberService?version=1.0.0&methods=aaa,bbb&application=morgan&weight=10", "methods", "ccc,ddd"));
    assertEquals("dubbo://172.22.3.91:20880/memberService?version=1.0.0&methods=$ccc,$ddd&application=morgan&weight=10", ParseUtils.replaceParameter("dubbo://172.22.3.91:20880/memberService?version=1.0.0&methods=$aaa,$bbb&application=morgan&weight=10", "methods", "$ccc,$ddd"));
}

